{
  "name": "Thorlabs APT通信端口",
  "name_en": "Thorlabs APT Communication Port",
  "manufacturer": "Thorlabs",
  "description": "用于Thorlabs APT位移台/控制器通信的非物理软件组件。它负责通过串口样式端口发送和接收消息、运行消息处理循环、提供文件描述符访问，并读取控制器序列号、通道数量及已连接平台信息，适合在实验自动化中管理单控制器或卡槽式控制器的通信连接。",
  "description_en": "A non-physical software component for communicating with Thorlabs APT motion-stage controllers. It sends and receives protocol messages over a serial-style port, runs the message-processing loop, exposes the file descriptor, and retrieves controller serial number, channel count, and connected stage information for automation workflows involving single-controller or card-slot controllers.",
  "actions": [
    {
      "action_name": "auto-send_message",
      "description": "发送通信消息",
      "description_en": "send a communication message"
    },
    {
      "action_name": "auto-fileno",
      "description": "获取文件描述符",
      "description_en": "get the file descriptor"
    },
    {
      "action_name": "auto-recv_message",
      "description": "接收通信消息",
      "description_en": "receive a communication message"
    },
    {
      "action_name": "auto-run",
      "description": "运行消息处理循环",
      "description_en": "run the message-processing loop"
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号",
      "description_en": "get serial number"
    },
    {
      "action_name": "auto-channel_count",
      "description": "获取通道数量",
      "description_en": "get channel count"
    },
    {
      "action_name": "auto-get_stages",
      "description": "获取已连接平台信息",
      "description_en": "get connected stage information"
    },
    {
      "action_name": "auto-create",
      "description": "创建通信端口对象",
      "description_en": "create a communication port object"
    }
  ],
  "tag_hints": [
    "Thorlabs APT",
    "serial communication",
    "motion controller communication",
    "stage discovery",
    "controller serial number",
    "multi-channel controller",
    "card slot controller"
  ]
}

